package quiz_button

import (
	"main/internal/quiz/model/quiz_team"

	"github.com/google/uuid"
)

// QuizButton is a preconfigured ESP32 button: a stable button id -> quiz team mapping.
// The id is generated by the server and flashed into the device once, together with the event id.
type QuizButton struct {
	ID         string             `gorm:"type:varchar(64);primaryKey" json:"id"`
	QuizTeamID uuid.UUID          `gorm:"type:uuid;not null;index" json:"quiz_team_id"`
	QuizTeam   quiz_team.QuizTeam `gorm:"foreignKey:QuizTeamID;constraint:OnUpdate:CASCADE,OnDelete:CASCADE;" json:"quiz_team"`
}

func (QuizButton) TableName() string {
	return "quiz_buttons"
}
